import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Agent","description":"","frontmatter":{"title":"Agent"},"headers":[],"relativePath":"docs/settings/agent.md","filePath":"docs/settings/agent.md","lastUpdated":1791494193000}'),s={name:"docs/settings/agent.md"};function n(i,e,h,l,d,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h1><p>Settings → Agent controls how OrbySystems&#39;s agent behaves while it works on a request — how much context it keeps around, what it&#39;s allowed to do in a browser, whether it can search the web, and the sandbox it runs generated code in. Browser, Web Search, and Sandbox are sub-sections of this same page.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><p>How much context OrbySystems keeps around while working on a request — useful to tune if you&#39;re using a model with a smaller context window, or want tighter control over how long a query can run.</p><ul><li><strong>Max tool result % of context</strong> — truncates a single tool result once it would take up more than this share of the model&#39;s context window.</li><li><strong>Max history messages</strong> — how many past turns of a conversation are kept before older ones are dropped.</li><li><strong>Max iterations</strong> — the most turns (tool calls and responses) OrbySystems will take to answer a single query, so a query can&#39;t run away indefinitely.</li></ul><p>Each of these can be turned off (set to 0) if you&#39;d rather not cap it.</p><h2 id="browser" tabindex="-1">Browser <a class="header-anchor" href="#browser" aria-label="Permalink to &quot;Browser&quot;">​</a></h2><p>Controls what the agent is allowed to do when it drives a browser on your behalf — for example, downloading a statement or looking up a home value. Site visits the agent wants to make can require your approval; this section is where those approvals and any remembered site decisions live.</p><h2 id="web-search" tabindex="-1">Web Search <a class="header-anchor" href="#web-search" aria-label="Permalink to &quot;Web Search&quot;">​</a></h2><p>Controls whether — and how — OrbySystems can reach out to the web while answering a question.</p><h3 id="web-fetch-and-web-search" tabindex="-1">Web Fetch and Web Search <a class="header-anchor" href="#web-fetch-and-web-search" aria-label="Permalink to &quot;Web Fetch and Web Search&quot;">​</a></h3><p>Two independent toggles: <strong>Web Fetch</strong> lets OrbySystems read a specific web page you point it at, and <strong>Web Search</strong> lets it search the web for titles, links, and snippets. Both are off unless you turn them on.</p><h3 id="search-providers" tabindex="-1">Search providers <a class="header-anchor" href="#search-providers" aria-label="Permalink to &quot;Search providers&quot;">​</a></h3><p>With Web Search enabled, choose which provider(s) to use — DuckDuckGo (no API key needed), or Brave, Tavily, Perplexity, or a self-hosted SearXNG instance (each configured with its own API key or URL).</p><h3 id="network-and-caching" tabindex="-1">Network and caching <a class="header-anchor" href="#network-and-caching" aria-label="Permalink to &quot;Network and caching&quot;">​</a></h3><p>An optional proxy applies to every provider. Search results are cached so repeated queries don&#39;t re-fetch. The similarity threshold controls how close a new query must be to an earlier query before OrbySystems reuses the cached result; higher values are stricter. Clear the cache from this page if you want the next search to pull fresh results.</p><h2 id="sandbox" tabindex="-1">Sandbox <a class="header-anchor" href="#sandbox" aria-label="Permalink to &quot;Sandbox&quot;">​</a></h2><p>Where you control the general sandbox OrbySystems uses to run LLM-generated Python safely, without exposing your local files to it. See <a href="/docs/privacy-and-security/sandboxing">Sandboxing</a> for the concept, including how this differs from the separate, fully network-isolated sandbox statement parsers always run in (which isn&#39;t configurable here — see that page for why).</p><h3 id="allowed-hosts" tabindex="-1">Allowed hosts <a class="header-anchor" href="#allowed-hosts" aria-label="Permalink to &quot;Allowed hosts&quot;">​</a></h3><p>The sandbox blocks all network access by default. If you need it to reach specific external sources — for example, to install a Python library a generated script depends on — add trusted hostnames (or glob patterns) to the allowed list here, one per line.</p><p>Saving changes to this list can require rebuilding the sandbox, offered as a separate <strong>Save and Rebuild</strong> action.</p>',21)])])}const b=a(s,[["render",n]]);export{p as __pageData,b as default};
